525			if _, seen := clientByHost[t.region.host]; seen {
526				continue
527			}
528			if _, seen := clientErrByHost[t.region.host]; seen {
529				continue
530			}
531			c, err := coreapi.NewForCluster(ctx, t.region.host)
532			if err != nil {
533				clientErrByHost[t.region.host] = err
534			} else {
535				clientByHost[t.region.host] = c
536			}
537		}
