539		// Docker-pull-style live progress: one line per (repo, region), each
540		// updating independently as its CreateMirror + clone poll advance.
541		labels := make([]string, len(targets))
542		for i, t := range targets {
543			labels[i] = t.owner + "/" + t.repo + " @ " + t.region.host
544		}
