570	// error: every outcome is folded into the mirrorResult so a single failure
571	// can't sink the batch. report (may be nil) is called as the mirror moves
572	// through its phases so the caller can render live progress; the final call has
573	// final=true and ok set to whether it succeeded.
574	func createOneMirror(ctx context.Context, t mirrorTarget, c *coreapi.Client, clientErr error, noWait bool, waitTimeout time.Duration, report func(status string, final, ok bool)) mirrorResult {
575		if report == nil {
576			report = func(string, bool, bool) {}
577		}
578		res := mirrorResult{owner: t.owner, repo: t.repo, regionLabel: regionLabel(t.region)}
579		if clientErr != nil {
580			res.status, res.err = mirrorStatusError, clientErr
581			report(mirrorStatusError, true, false)
582			return res
583		}
584		report("creating", false, false)
585		// Same create-then-wait path as the one-shot `repo mirror create <url>`
586		// (createAndAwaitMirror), so both report identical lifecycle states. The
587		// per-poll status drives this mirror's progress line.
588		outcome, err := createAndAwaitMirror(ctx, c, t.owner, t.repo, t.region.host, noWait, waitTimeout, nil,
589			func(s coreapi.MirrorStatus) { report(string(s), false, false) })
590		if outcome.created == nil {
591			res.status, res.err = mirrorStatusError, renderCoreError(err)
592			report(mirrorStatusError, true, false)
593			return res
594		}
595		res.cloneURL = outcome.created.MirrorUrl
596	
597		if outcome.created.Suspended {
598			// An admin suspended this existing placement, so it won't be served.
599			// Surface it as a distinct status and set an error so the batch exits
600			// non-zero, matching the one-shot: a suspended mirror isn't a success.
601			res.status, res.err = mirrorStatusSuspended, errors.New("suspended by an admin; won't be usable")
602			report(mirrorStatusSuspended, true, false)
603			return res
604		}
605	
606		if !outcome.polled {
607			if outcome.created.Empty {
608				res.status = mirrorStatusEmpty
609			} else {
610				res.status = mirrorStatusRegistered
611			}
612			report(res.status, true, true)
613			return res
614		}
615	
616		// nonTerminal classifies a still-processing/unknown result: the poll ended
617		// without a terminal status, so the wait timed out or a poll call errored.
618		nonTerminal := func() {
619			if errors.Is(err, context.DeadlineExceeded) {
620				res.status, res.err = mirrorStatusTimedOut, err
621			} else {
622				res.status, res.err = mirrorStatusError, err
623			}
624		}
625		switch outcome.status {
626		case coreapi.MirrorStatusReady:
627			res.status = mirrorStatusReady
628		case coreapi.MirrorStatusSuspended:
629			res.status, res.err = mirrorStatusSuspended, errors.New("the mirror is suspended; contact support")
630		case coreapi.MirrorStatusFailed:
631			res.status, res.err = mirrorStatusFailed, errors.New("the initial clone failed; contact support")
632		case coreapi.MirrorStatusProcessing:
633			nonTerminal()
634		default:
635			nonTerminal()
636		}
637		report(res.status, true, res.err == nil)
638		return res
639	}

